const MAX_QUESTION: usize = 512;

/// Returned in `knowledge` when the knowledge base has no match, so the
/// output's `knowledge` list is never empty.
const NO_MATCH: &str = "no knowledge-base entries matched";

/// Truncate `s` to at most `max` bytes, cutting only on a char boundary.
fn bound(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

/// Percent-encode `s` for use as a URL query value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

